    result, path = [], []
    def walk(node, rest):
        if node is None:
            return
        path.append(node.val)                        # choose
        if node.left is None and node.right is None and node.val == rest:
            result.append(list(path))                # a copy: the list changes later
        walk(node.left, rest - node.val)             # explore
        walk(node.right, rest - node.val)
        path.pop()                                   # unchoose
